insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e6ce0c14-e749-53f4-b04c-425d6bb797a2', 'aaaaaaaa-0000-0000-0000-000000000009', '170', '‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَيُّهَا النَّاسُ ‏ ‏إِنَّكُمْ سَتُحْدِثُونَ وَيُحْدَثُ لَكُمْ فَإِذَا رَأَيْتُمْ مُحْدَثَةً فَعَلَيْكُمْ بِالْأَمْرِ الْأَوَّلِ ‏ ‏قَالَ ‏ ‏حَفْصٌ ‏ ‏كُنْتُ أُسْنِدُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏ثُمَّ دَخَلَنِي مِنْهُ شَكٌّ ‏', 'سنن الدارمي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('89bd9606-14d7-5fe2-a039-822aae8a95d7', 'aaaaaaaa-0000-0000-0000-000000000009', '171', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّلْتِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏لِأَبِي مَسْعُودٍ ‏ ‏أَلَمْ أُنْبَأْ ‏ ‏أَوْ أُنْبِئْتُ ‏ ‏أَنَّكَ ‏ ‏تُفْتِي وَلَسْتَ بِأَمِيرٍ وَلِّ ‏ ‏حَارَّهَا ‏ ‏مَنْ تَوَلَّى ‏ ‏قَارَّهَا ‏', 'سنن الدارمي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b8a6cba1-2fae-538f-8f1d-3c7d259f07c9', 'aaaaaaaa-0000-0000-0000-000000000009', '172', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِنَّ الَّذِي يُفْتِي النَّاسَ فِي كُلِّ مَا ‏ ‏يُسْتَفْتَى لَمَجْنُونٌ ‏', 'سنن الدارمي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('60860334-db23-540e-9ec9-7e932a3b2e82', 'aaaaaaaa-0000-0000-0000-000000000009', '173', '‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏إِنَّمَا يُفْتِي النَّاسَ ثَلَاثَةٌ رَجُلٌ إِمَامٌ أَوْ وَالٍ وَرَجُلٌ يَعْلَمُ ‏ ‏نَاسِخَ ‏ ‏الْقُرْآنِ مِنْ ‏ ‏الْمَنْسُوخِ ‏ ‏قَالُوا يَا ‏ ‏حُذَيْفَةُ ‏ ‏وَمَنْ ذَاكَ قَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏أَوْ أَحْمَقُ مُتَكَلِّفٌ ‏', 'سنن الدارمي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a51be1f8-b77f-5db0-a545-8fe6116985bf', 'aaaaaaaa-0000-0000-0000-000000000009', '174', '‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ حُذَيْفَةَ ‏ ‏قَالَ قَالَ ‏ ‏حُذَيْفَةُ ‏ ‏إِنَّمَا يُفْتِي النَّاسَ أَحَدُ ثَلَاثَةٍ رَجُلٌ عَلِمَ ‏ ‏نَاسِخَ ‏ ‏الْقُرْآنِ مِنْ ‏ ‏مَنْسُوخِهِ ‏ ‏قَالُوا وَمَنْ ذَاكَ قَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏قَالَ وَأَمِيرٌ لَا يَجِدُ بُدًّا أَوْ أَحْمَقُ مُتَكَلِّفٌ ‏ ‏ثُمَّ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏فَلَسْتُ بِوَاحِدٍ مِنْ هَذَيْنِ وَأَرْجُو أَنْ لَا أَكُونَ الثَّالِثَ ‏', 'سنن الدارمي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b333c3a4-9142-54b5-939f-5301c2d371d2', 'aaaaaaaa-0000-0000-0000-000000000009', '175', '‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَنْ عَلِمَ مِنْكُمْ عِلْمًا فَلْيَقُلْ بِهِ وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلْ لِمَا لَا يَعْلَمُ اللَّهُ أَعْلَمُ فَإِنَّ الْعَالِمَ إِذَا سُئِلَ عَمَّا لَا يَعْلَمُ قَالَ اللَّهُ أَعْلَمُ وَقَدْ قَالَ اللَّهُ لِرَسُولِهِ ‏ { ‏قُلْ لَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنْ ‏ ‏الْمُتَكَلِّفِينَ ‏ }', 'سنن الدارمي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d3d34720-b5e8-5246-b596-d120fa7a5cee', 'aaaaaaaa-0000-0000-0000-000000000009', '176', '‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَبِي رَجَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَلَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى ‏ ‏قَالَ فِي خُطْبَتِهِ ‏ ‏مَنْ عَلِمَ عِلْمًا فَلْيُعَلِّمْهُ النَّاسَ وَإِيَّاهُ أَنْ يَقُولَ مَا لَا عِلْمَ لَهُ بِهِ ‏ ‏فَيَمْرُقَ ‏ ‏مِنْ الدِّينِ وَيَكُونَ مِنْ الْمُتَكَلِّفِينَ ‏', 'سنن الدارمي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2b08522e-7a2c-5699-8f4d-78c8744441fc', 'aaaaaaaa-0000-0000-0000-000000000009', '177', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏وَزَاذَانَ ‏ ‏قَالَا قَالَ ‏ ‏عَلِيٌّ ‏ ‏وَا بَرْدَهَا عَلَى الْكَبِدِ إِذَا سُئِلْتُ عَمَّا لَا أَعْلَمُ أَنْ أَقُولَ اللَّهُ أَعْلَمُ ‏', 'سنن الدارمي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3997f3fa-e4e7-5cd3-8ccd-c01db51da9cb', 'aaaaaaaa-0000-0000-0000-000000000009', '178', '‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏يَا بَرْدَهَا عَلَى الْكَبِدِ أَنْ تَقُولَ لِمَا لَا تَعْلَمُ اللَّهُ أَعْلَمُ ‏', 'سنن الدارمي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4bae3977-b18f-5ca8-8863-f0ef63ed23a4', 'aaaaaaaa-0000-0000-0000-000000000009', '179', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَيْرُ بْنُ عَرْفَجَةَ ‏ ‏حَدَّثَنَا ‏ ‏رَزِينٌ أَبُو النُّعْمَانِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏قَالَ ‏ ‏إِذَا سُئِلْتُمْ عَمَّا لَا تَعْلَمُونَ فَاهْرُبُوا قَالُوا وَكَيْفَ الْهَرَبُ يَا أَمِيرَ الْمُؤْمِنِينَ قَالَ تَقُولُونَ اللَّهُ أَعْلَمُ ‏', 'سنن الدارمي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fa07a949-00de-544b-be3f-6b304b60a185', 'aaaaaaaa-0000-0000-0000-000000000009', '180', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏عَزْرَةَ التَّمِيمِيِّ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏وَا بَرْدَهَا عَلَى الْكَبِدِ ‏ ‏ثَلَاثَ مَرَّاتٍ ‏ ‏قَالُوا وَمَا ذَلِكَ يَا أَمِيرَ الْمُؤْمِنِينَ قَالَ أَنْ يُسْأَلَ الرَّجُلُ عَمَّا لَا يَعْلَمُ فَيَقُولُ اللَّهُ أَعْلَمُ ‏', 'سنن الدارمي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
